def comps(g, val):
 h,w=len(g),len(g[0]); seen=set(); out=[]
 for r in range(h):
  for c in range(w):
   if g[r][c]!=val or (r,c) in seen:continue
   stack=[(r,c)];seen.add((r,c)); cc=[]
   while stack:
    p=stack.pop();cc.append(p)
    for q in ((p[0]-1,p[1]),(p[0]+1,p[1]),(p[0],p[1]-1),(p[0],p[1]+1)):
     if 0<=q[0]<h and 0<=q[1]<w and q not in seen and g[q[0]][q[1]]==val:
      seen.add(q);stack.append(q)
   out.append(cc)
 return out
